problems.starterCode:
.shell {
  width: 100%;
  /* 최대 너비와 가운데 배치를 완성하세요 */
}

.gallery {
  display: grid;
  gap: 16px;
}

/* 900px 이하와 520px 이하 규칙을 추가하세요 */

problems.answer:
.gallery {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

@media (max-width: 900px) {
  .gallery { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 520px) {
  .gallery { grid-template-columns: 1fr; }
}

.travel-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}

@media (max-width: 900px) {
  .travel-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 600px) {
  .travel-list { grid-template-columns: 1fr; }
}

problems.starterCode:
.works {
  display: grid;
  gap: 24px;
}

/* 기본 열과 좁은 화면 열을 작성하세요 */

problems.answer:
.works {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

@media (max-width: 700px) {
  .works { grid-template-columns: 1fr; }
}

problems.starterCode:
.site-nav { display: flex; align-items: center; justify-content: space-between; }
.nav-links { display: flex; gap: 16px; }
.menu-button { /* 기본 표시 상태 */ }

@media (max-width: 640px) {
  /* 두 요소의 표시 상태를 바꾸세요 */
}

problems.answer:
.site-nav { display: flex; align-items: center; justify-content: space-between; }
.nav-links { display: flex; gap: 16px; }
.menu-button { display: none; }

@media (max-width: 640px) {
  .nav-links { display: none; }
  .menu-button { display: inline-flex; }
}

problems.starterCode:
.fluid-hero h2 {
  /* clamp()를 사용하세요 */
}

.fluid-hero img {
  /* 반응형 이미지 기본값 */
}

problems.answer:
.fluid-hero h2 {
  font-size: clamp(28px, 6vw, 56px);
}

.fluid-hero img {
  max-width: 100%;
  height: auto;
}

problems.starterCode:
.catalog { padding: 12px; }
.catalog-grid { display: grid; grid-template-columns: 1fr; gap: 16px; }

/* min-width 600px과 1000px 규칙을 추가하세요 */

problems.answer:
.catalog { padding: 12px; }
.catalog-grid { display: grid; grid-template-columns: 1fr; gap: 16px; }

@media (min-width: 600px) {
  .catalog { padding: 20px; }
  .catalog-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (min-width: 1000px) {
  .catalog { padding: 24px; }
  .catalog-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
